CREATE TABLE public.staff_permissions (user_id uuid NOT NULL, permission text NOT NULL, granted_by uuid NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,permission), CONSTRAINT staff_permission_key CHECK(permission IN ('customers.view','customers.manage','sellers.view','sellers.manage','ads.view','ads.manage')));
GRANT SELECT ON public.staff_permissions TO authenticated;
GRANT ALL ON public.staff_permissions TO service_role;
ALTER TABLE public.staff_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_permissions_read ON public.staff_permissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.has_staff_permission(_permission text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND NOT coalesce(is_banned,false) AND coalesce(account_status,'active')='active') AND (public.has_role(auth.uid(),'admin') OR (public.has_role(auth.uid(),'moderator') AND EXISTS(SELECT 1 FROM public.staff_permissions WHERE user_id=auth.uid() AND (permission=_permission OR permission=replace(_permission,'.view','.manage'))))) $$;
REVOKE ALL ON FUNCTION public.has_staff_permission(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_staff_permission(text) TO authenticated,service_role;
CREATE FUNCTION public.set_staff_permissions(_user_id uuid,_permissions text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'not_authorized'; END IF; IF _user_id=auth.uid() OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='moderator') OR public.has_role(_user_id,'admin') THEN RAISE EXCEPTION 'moderator_required'; END IF; IF _permissions IS NULL OR EXISTS(SELECT 1 FROM unnest(_permissions) k WHERE k IS NULL OR k NOT IN ('customers.view','customers.manage','sellers.view','sellers.manage','ads.view','ads.manage')) THEN RAISE EXCEPTION 'invalid_permissions'; END IF; DELETE FROM public.staff_permissions WHERE user_id=_user_id; INSERT INTO public.staff_permissions(user_id,permission,granted_by) SELECT _user_id,k,auth.uid() FROM (SELECT DISTINCT unnest(_permissions) k) s; PERFORM public.log_admin_action('supervisor_permissions_changed',jsonb_build_object('user_id',_user_id,'permissions',_permissions)); END $$;
REVOKE ALL ON FUNCTION public.set_staff_permissions(uuid,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_staff_permissions(uuid,text[]) TO authenticated,service_role;
CREATE FUNCTION public.get_my_staff_permissions() RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(k),'{}'::text[]) FROM unnest(ARRAY['customers.view','customers.manage','sellers.view','sellers.manage','ads.view','ads.manage']) k WHERE public.has_staff_permission(k) $$;
REVOKE ALL ON FUNCTION public.get_my_staff_permissions() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_my_staff_permissions() TO authenticated,service_role;
CREATE FUNCTION public.can_manage_staff_account(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id<>auth.uid() AND (public.has_role(auth.uid(),'super_admin') OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('admin','super_admin','moderator'))) AND public.has_staff_permission(CASE WHEN EXISTS(SELECT 1 FROM public.seller_applications WHERE user_id=_user_id) OR EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND role='vendor') THEN 'sellers.manage' ELSE 'customers.manage' END) $$;
REVOKE ALL ON FUNCTION public.can_manage_staff_account(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_staff_account(uuid) TO authenticated,service_role;
CREATE FUNCTION public.admin_account_directory(_kind text,_search text DEFAULT '',_offset integer DEFAULT 0,_limit integer DEFAULT 50) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF _kind NOT IN ('buyers','sellers','stores') OR NOT public.has_staff_permission(CASE WHEN _kind='buyers' THEN 'customers.view' ELSE 'sellers.view' END) THEN RAISE EXCEPTION 'not_authorized'; END IF; WITH matches AS (SELECT p.id,p.full_name,p.phone,p.role,p.account_status,p.status_reason,p.is_banned,p.created_at,u.email,sa.id application_id,sa.store_name,sa.owner_name,sa.contact_phone,sa.contact_email,sa.governorate,sa.city,sa.address,sa.status store_status,sa.logo_url,sa.rejection_reason,(SELECT count(*) FROM public.products pr WHERE pr.vendor_id=p.id) products_count,(SELECT count(DISTINCT oi.order_id) FROM public.order_items oi WHERE oi.vendor_id=p.id) orders_count FROM public.profiles p LEFT JOIN auth.users u ON u.id=p.id LEFT JOIN LATERAL(SELECT * FROM public.seller_applications WHERE user_id=p.id ORDER BY created_at DESC LIMIT 1) sa ON true WHERE (CASE WHEN _kind='buyers' THEN p.role='customer' AND sa.id IS NULL WHEN _kind='stores' THEN sa.id IS NOT NULL ELSE p.role='vendor' OR sa.id IS NOT NULL END) AND (coalesce(_search,'')='' OR concat_ws(' ',p.id,p.full_name,p.phone,u.email,sa.store_name,sa.contact_phone,sa.contact_email,sa.city) ILIKE '%'||left(_search,200)||'%')), page AS (SELECT * FROM matches ORDER BY created_at DESC,id LIMIT greatest(1,least(_limit,100)) OFFSET greatest(0,_offset)) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(page)) FROM page),'[]'::jsonb),'total',(SELECT count(*) FROM matches)) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_account_directory(text,text,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_account_directory(text,text,integer,integer) TO authenticated,service_role;
CREATE FUNCTION public.admin_account_detail(_user_id uuid,_offset integer DEFAULT 0,_limit integer DEFAULT 20) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE seller boolean; result jsonb; cap integer:=greatest(1,least(_limit,100)); skip integer:=greatest(0,_offset); BEGIN seller:=EXISTS(SELECT 1 FROM public.seller_applications WHERE user_id=_user_id) OR EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND role='vendor'); IF NOT public.has_staff_permission(CASE WHEN seller THEN 'sellers.view' ELSE 'customers.view' END) THEN RAISE EXCEPTION 'not_authorized'; END IF; SELECT jsonb_build_object('profile',to_jsonb(p)||jsonb_build_object('email',u.email,'roles',(SELECT coalesce(jsonb_agg(role),'[]'::jsonb) FROM public.user_roles WHERE user_id=p.id)), 'store',(SELECT to_jsonb(sa) FROM public.seller_applications sa WHERE user_id=p.id ORDER BY created_at DESC LIMIT 1), 'addresses',CASE WHEN NOT seller THEN (SELECT coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb) FROM public.delivery_addresses a WHERE user_id=p.id) ELSE '[]'::jsonb END, 'products',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) FROM (SELECT id,name,price,currency,stock_quantity,is_active,moderation_status,image_url FROM public.products WHERE vendor_id=p.id ORDER BY created_at DESC,id LIMIT cap OFFSET skip) q), 'products_total',(SELECT count(*) FROM public.products WHERE vendor_id=p.id), 'orders',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) FROM (SELECT o.id,o.created_at,o.status,o.total_amount,o.currency FROM public.orders o WHERE o.customer_id=p.id OR EXISTS(SELECT 1 FROM public.order_items oi WHERE oi.order_id=o.id AND oi.vendor_id=p.id) ORDER BY o.created_at DESC,o.id LIMIT cap OFFSET skip) q), 'orders_total',(SELECT count(*) FROM public.orders o WHERE o.customer_id=p.id OR EXISTS(SELECT 1 FROM public.order_items oi WHERE oi.order_id=o.id AND oi.vendor_id=p.id)), 'activity',(SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) FROM (SELECT id,action_type,created_at FROM public.activity_logs WHERE user_id=p.id ORDER BY created_at DESC LIMIT 20) q)) INTO result FROM public.profiles p LEFT JOIN auth.users u ON u.id=p.id WHERE p.id=_user_id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.admin_account_detail(uuid,integer,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_account_detail(uuid,integer,integer) TO authenticated,service_role;
DO $$ DECLARE n text; d text; BEGIN FOREACH n IN ARRAY ARRAY['admin_activate_user','admin_ban_user','admin_suspend_user'] LOOP SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=n; IF strpos(d,'IF NOT public.has_role(auth.uid(), ''admin'')')=0 THEN RAISE EXCEPTION 'unexpected_account_guard: %',n; END IF; EXECUTE replace(d,'IF NOT public.has_role(auth.uid(), ''admin'')','IF NOT public.can_manage_staff_account(_user_id)'); END LOOP; FOREACH n IN ARRAY ARRAY['suspend_seller','reactivate_seller'] LOOP SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=n; IF strpos(d,'IF NOT public.has_role(auth.uid(),''admin'')')=0 THEN RAISE EXCEPTION 'unexpected_store_guard: %',n; END IF; EXECUTE replace(d,'IF NOT public.has_role(auth.uid(),''admin'')','IF NOT public.has_staff_permission(''sellers.manage'') OR NOT public.can_manage_staff_account(_user_id)'); END LOOP; END $$;
DROP POLICY "Admins can view all profiles" ON public.profiles;
CREATE POLICY "Admins can view all profiles" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY owner_read_staff_roles ON public.user_roles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
DROP POLICY "Admins can manage native ads" ON public.native_ads;
CREATE POLICY staff_read_native_ads ON public.native_ads FOR SELECT TO authenticated USING(public.has_staff_permission('ads.view'));
CREATE POLICY staff_insert_native_ads ON public.native_ads FOR INSERT TO authenticated WITH CHECK(public.has_staff_permission('ads.manage'));
CREATE POLICY staff_update_native_ads ON public.native_ads FOR UPDATE TO authenticated USING(public.has_staff_permission('ads.manage')) WITH CHECK(public.has_staff_permission('ads.manage'));
CREATE POLICY staff_delete_native_ads ON public.native_ads FOR DELETE TO authenticated USING(public.has_staff_permission('ads.manage'));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.native_ads TO authenticated;
GRANT ALL ON public.native_ads TO service_role;
CREATE POLICY delegated_ad_image_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='product-images' AND (storage.foldername(name))[1]='platform' AND (storage.foldername(name))[2]='banners' AND public.has_staff_permission('ads.manage'));
CREATE POLICY delegated_ad_image_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='product-images' AND (storage.foldername(name))[1]='platform' AND (storage.foldername(name))[2]='banners' AND public.has_staff_permission('ads.manage'));
CREATE FUNCTION public.validate_admin_ad() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.placement NOT IN ('home','category','search','product') THEN RAISE EXCEPTION 'invalid_ad_placement'; END IF; IF NEW.start_date IS NOT NULL AND NEW.end_date IS NOT NULL AND NEW.end_date<=NEW.start_date THEN RAISE EXCEPTION 'invalid_ad_dates'; END IF; IF NEW.cta_url IS NOT NULL AND (NEW.cta_url !~ '^/[^/\\]' AND NEW.cta_url<>'/' OR NEW.cta_url ~ '[[:cntrl:]\\]') THEN RAISE EXCEPTION 'invalid_ad_destination'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_admin_ad_before_write BEFORE INSERT OR UPDATE OF placement,start_date,end_date,cta_url ON public.native_ads FOR EACH ROW EXECUTE FUNCTION public.validate_admin_ad();